using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// Train model and register PredictionEnginePool (thread-safe for ASP.NET Core)
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "ChurnModel.zip");

TrainAndSaveModel(mlContext, dataPath, modelPath);

builder.Services.AddPredictionEnginePool<CustomerInput, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST /predict with Age, Income, Region, PurchaseHistory");

app.MapPost("/predict", (PredictionEnginePool<CustomerInput, ChurnPrediction> pool, CustomerInput input) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel,
        Probability = prediction.Probability,
        Score = prediction.Score,
    });
});

app.Run();

static void TrainAndSaveModel(MLContext mlContext, string dataPath, string modelPath)
{
    var data = mlContext.Data.LoadFromTextFile<CustomerInput>(
        dataPath, hasHeader: true, separatorChar: ',');

    var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

    var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerInput.Region))
        .Append(mlContext.Transforms.Concatenate("Features",
            nameof(CustomerInput.Age),
            nameof(CustomerInput.Income),
            "RegionEncoded",
            nameof(CustomerInput.PurchaseHistory)))
        .Append(mlContext.Transforms.NormalizeMinMax("Features"))
        .Append(mlContext.BinaryClassification.Trainers.FastTree(
            labelColumnName: "Label",
            featureColumnName: "Features"));

    var model = pipeline.Fit(split.TrainSet);

    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");

    Console.WriteLine("=== Churn Model Evaluation ===");
    Console.WriteLine($"  AUC:      {metrics.AreaUnderRocCurve:F4}");
    Console.WriteLine($"  F1 Score: {metrics.F1Score:F4}");
    Console.WriteLine($"  Accuracy: {metrics.Accuracy:F4}");

    mlContext.Model.Save(model, data.Schema, modelPath);
    Console.WriteLine($"Model saved to {modelPath}");
}

// --- Data models ---

public class CustomerInput
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4), ColumnName("Label")]
    public bool Churned { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }

    public float Score { get; set; }
}

